#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn rejects_unknown_fields() {
        let raw = r#"{"ok":true,"data":{},"debug_token":"nope"}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(raw).is_err());
    }

    #[test]
    fn rejects_invalid_discriminated_branch() {
        let raw = r#"{"ok":false,"data":{}}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(raw).is_err());
    }

    #[test]
    fn rejects_explicit_null_for_optional_non_nullable_fields() {
        let null_meta = r#"{"ok":true,"data":{},"meta":null}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(null_meta).is_err());
        let null_request_id = r#"{"ok":true,"data":{},"meta":{"request_id":null}}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(null_request_id).is_err());
    }

    #[test]
    fn measures_json_schema_lengths_in_unicode_code_points() {
        let accepted = serde_json::json!({
            "ok": false,
            "error": {
                "code": "unicode.boundary",
                "message": "🙂".repeat(2048),
                "path": ["🙂".repeat(128)],
                "retryable": false
            }
        });
        assert!(serde_json::from_value::<ResultEnvelope<Value>>(accepted).is_ok());

        let rejected = serde_json::json!({
            "ok": false,
            "error": {
                "code": "unicode.overflow",
                "message": "🙂".repeat(2049),
                "retryable": false
            }
        });
        assert!(serde_json::from_value::<ResultEnvelope<Value>>(rejected).is_err());
    }

    #[test]
    fn enforces_metadata_integer_maximum() {
        let raw = r#"{"ok":true,"data":{},"meta":{"omitted_bytes":2147483648}}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(raw).is_err());
    }

    #[test]
    fn matches_the_schema_control_character_range_exactly() {
        let c1_control_allowed_by_schema = serde_json::json!({
            "ok": false,
            "error": {
                "code": "unicode.c1",
                "message": "allowed\u{0085}by-schema",
                "retryable": false
            }
        });
        assert!(
            serde_json::from_value::<ResultEnvelope<Value>>(c1_control_allowed_by_schema).is_ok()
        );
    }

    #[test]
    fn accepts_failure() {
        let raw = r#"{"ok":false,"error":{"code":"upstream.timeout","message":"timed out","retryable":true}}"#;
        assert!(serde_json::from_str::<ResultEnvelope<Value>>(raw).is_ok());
    }

    #[test]
    fn constructors_preserve_discriminator_invariants() {
        let value = ResultEnvelope::success(serde_json::json!({"healthy": true}));
        assert_eq!(serde_json::to_value(value).unwrap()["ok"], true);
        let error = SafeError::simple("upstream.timeout", "timed out", true).unwrap();
        let value: ResultEnvelope<Value> = ResultEnvelope::failure(error);
        assert_eq!(serde_json::to_value(value).unwrap()["ok"], false);
    }

    #[test]
    fn path_errors_include_the_component_index() {
        let error = SafeError::new("bad.path", "bad path", vec![String::new()], false)
            .expect_err("empty path component must fail");
        assert_eq!(error.code, "min_length");
        assert_eq!(error.path, "$/error/path/0");
    }

    #[test]
    fn value_validator_returns_stable_codes_and_paths() {
        let cases = [
            (
                serde_json::json!({"ok": true, "data": {}, "meta": null}),
                "type",
                "$/meta",
            ),
            (
                serde_json::json!({
                    "ok": false,
                    "error": {
                        "code": "bad.path",
                        "message": "bad path",
                        "path": [""],
                        "retryable": false
                    }
                }),
                "min_length",
                "$/error/path/0",
            ),
            (
                serde_json::json!({
                    "ok": false,
                    "data": {},
                    "error": {
                        "code": "bad.branch",
                        "message": "mixed",
                        "retryable": false
                    }
                }),
                "additional_properties",
                "$/data",
            ),
        ];
        for (value, code, path) in cases {
            let error = validate_result_envelope_value(&value).expect_err("fixture must fail");
            assert_eq!(error.code, code);
            assert_eq!(error.path, path);
        }
    }
}
